def source_git_commit() -> str:
    """Bind package provenance to a clean, checked-out Git source."""
    import re
    repository = ROOT.parent

    def git(*args: str):
        return subprocess.run(['git', '-C', str(repository), *args], capture_output=True, text=True, check=False)
    identity = git('rev-parse', '--verify', 'HEAD')
    if identity.returncode or not re.fullmatch('[0-9a-f]{40}', identity.stdout.strip()):
        raise ValueError('an immutable Git source commit is required to package Bridge')
    status = git('status', '--porcelain', '--untracked-files=all', '--', 'agent_bridge/src', 'agent_bridge/scripts', 'agent_bridge/desktop_app')
    if status.returncode:
        raise ValueError('cannot verify package source worktree')
    excluded = ('/__pycache__/', '/.pytest_cache/', '/bin/', '/obj/', '/publish/', '/build/', '/dist/', '/.venv/', '/.build-venv/')
    for line in status.stdout.splitlines():
        path = line[3:].replace('\\', '/')
        if any((item in path for item in excluded)) or path.endswith(('.pyc', '.pyo')):
            continue
        if '.egg-info/' in path:
            continue
        raise ValueError('package source worktree has uncommitted code')
    return identity.stdout.strip()
